P = {}
for t, e in json.load(open("/audit/gen13.json")).items():
    P[t] = dict(src=S, why="неверные варианты «Неверно» / «Нельзя однозначно ответить без вычисления» не были ответами на задание и не имели смысла; заменены правдоподобными ошибочными вариантами с пояснением", dnew={int(a): tuple(b) for a, b in e["dnew"].items()}, drop=e["drop"])
P["G7_ALG_7_17.4"] = dict(src=S, why="$3^{15}=14348907$, $7^{10}=282475249$, значит $3^{15}<7^{10}$; ключ «>» неверен; варианты «Неверно» и «Нельзя однозначно ответить» заменены",
  k=r"$3^{15} < 7^{10}$", dnew={0: (r"$3^{15} > 7^{10}$", "Ученик решил, что $3^{15}$ больше, так как показатель $15$ больше $10$."), 1: (r"$3^{15} = 7^{10}$", "Ученик сравнил показатели и основания и решил, что числа равны.")})
